parameters.command:
={{ (() => {
  const defaultTmpDir = "/tmp";
  function resolveRuntimeTmpDir(value) {
    const normalized = String(value || "").trim().replace(/\\/g, "/").replace(/\/+$/g, "");
    if (normalized === defaultTmpDir || normalized.startsWith(`${defaultTmpDir}/`)) return normalized;
    return defaultTmpDir;
  }
  const tmpDir = resolveRuntimeTmpDir($vars.LIVIA_TMP_DIR);

  function str(v) {
    return (v === undefined || v === null) ? "" : String(v);
  }

  function basenameNoExt(name) {
    const n = str(name).split("/").pop();
    return n.replace(/\.[^.]+$/, "");
  }

  const groupKey = str($json.groupKey).trim();
  let base = groupKey.startsWith("dt:") ? groupKey.slice(3) : groupKey;
  if (!base) base = basenameNoExt($json.name);

  const payload = { tmpDir, base };

  return `node <<'NODE'
const fs = require('fs');
const path = require('path');

const payload = ${JSON.stringify(payload)};
const tmpDir = payload.tmpDir;
const base = payload.base;

const result = {
  tmpDir,
  base,
  deleted: [],
  skipped: [],
  failed: [],
};

function recordFailed(file, reason) {
  result.failed.push({ file, reason: String(reason && reason.message ? reason.message : reason) });
}

function isAllowedBase(value) {
  return /^[A-Za-z0-9_-]+$/.test(String(value || ""));
}

function isAllowedCleanupName(name) {
  if (!name.startsWith(base)) return false;
  const suffix = name.slice(base.length);
  return (
    /^\.(mp4|mov|m4v|webm|mkv|jpg|jpeg|png|webp)$/i.test(suffix) ||
    /^_temp\.[A-Za-z0-9]+$/i.test(suffix) ||
    /^_temp_cand_[0-9]+\.jpg$/i.test(suffix) ||
    /^_cand_[0-9]+\.jpg$/i.test(suffix) ||
    /^_temp_thumb\.jpg$/i.test(suffix) ||
    /^_thumb\.jpg$/i.test(suffix) ||
    /^_temp_frame_analysis\.json$/i.test(suffix) ||
    /^_frame_analysis\.json$/i.test(suffix) ||
    /^_compressed\.mp4$/i.test(suffix) ||
    /^_ig\.jpg$/i.test(suffix) ||
    /^_temp_compressed\.mp4$/i.test(suffix) ||
    /^_temp_ig\.jpg$/i.test(suffix)
  );
}

function isAllowedCleanupDir(name) {
  if (!name.startsWith(base)) return false;
  const suffix = name.slice(base.length);
  return /^_[A-Za-z0-9_-]+_assets_[A-Za-z0-9_-]+$/i.test(suffix) || /^_assets_[A-Za-z0-9_-]+$/i.test(suffix);
}

try {
  fs.mkdirSync(tmpDir, { recursive: true });

  if (!isAllowedBase(base)) {
    recordFailed("", "unsafe-or-empty-base");
    console.log(JSON.stringify(result));
    process.exit(0);
  }

  const entries = fs.readdirSync(tmpDir, { withFileTypes: true });
  for (const entry of entries) {
    if (entry.isDirectory()) {
      if (!isAllowedCleanupDir(entry.name)) continue;

      const fullPath = path.join(tmpDir, entry.name);
      try {
        fs.rmSync(fullPath, { recursive: true, force: true });
        result.deleted.push(entry.name + "/");
      } catch (error) {
        recordFailed(entry.name + "/", error);
      }
      continue;
    }

    if (!entry.isFile()) continue;
    if (!isAllowedCleanupName(entry.name)) continue;

    const fullPath = path.join(tmpDir, entry.name);
    try {
      fs.unlinkSync(fullPath);
      result.deleted.push(entry.name);
    } catch (error) {
      recordFailed(entry.name, error);
    }
  }

  console.log(JSON.stringify(result));
  process.exit(0);
} catch (error) {
  recordFailed("", error);
  console.log(JSON.stringify(result));
  process.exit(0);
}
NODE`;
})() }}

parameters.jsCode:
const items = $input.all();

function str(value, fallback = "") {
  return value === undefined || value === null ? fallback : String(value);
}

function inferMimeTypeFromName(name, fallback = "") {
  const lower = str(name, "").trim().toLowerCase();
  if (!lower) return fallback;
  if (/\.(mp4|m4v|webm|mkv)$/i.test(lower)) return "video/mp4";
  if (/\.mov$/i.test(lower)) return "video/quicktime";
  if (/\.(jpg|jpeg)$/i.test(lower)) return "image/jpeg";
  if (/\.png$/i.test(lower)) return "image/png";
  if (/\.webp$/i.test(lower)) return "image/webp";
  if (/\.heic$/i.test(lower)) return "image/heic";
  return fallback;
}

function baseDateTime(name) {
  const match = str(name, "").match(/^(\d{10})/);
  return match ? match[1] : "";
}

function publishTimeFromBase(value) {
  const match = str(value, "").match(/^(\d{2})(\d{2})(\d{2})(\d{2})(\d{2})$/);
  if (!match) return "";
  const [, dd, MM, yy, HH, mm] = match;
  return `20${yy}-${MM}-${dd}T${HH}:${mm}:00-03:00`;
}

function fileBase(value) {
  return str(value, "").replace(/.[^.]+$/, "");
}

function pushStoreKey(store, key, row) {
  const normalized = str(key, "").trim();
  if (!normalized || store[normalized]) return;
  store[normalized] = row;
}

const nowMs = Date.now();
const normalizedList = items.map((item, inputIndex) => {
  const current = (item && item.json && typeof item.json === "object") ? item.json : {};
  const id = str(current.id, "");
  const name = str(current.name, "");
  const mimeType = str(current.mimeType || inferMimeTypeFromName(name, ""), "");
  const normalizedMime = mimeType.toLowerCase();
  const supportedMedia = normalizedMime.startsWith("image/") || normalizedMime.startsWith("video/");
  const postPrefix = baseDateTime(name).slice(0, 10);
  const targetDate = postPrefix.slice(0, 6);
  const publishTime = publishTimeFromBase(postPrefix);
  const publishTimeMs = publishTime ? Date.parse(publishTime) : NaN;

  return {
    _inputIndex: inputIndex,
    _pairedItem: item && item.pairedItem ? item.pairedItem : { item: inputIndex },
    id,
    name,
    mimeType,
    postPrefix,
    targetDate,
    publishTime,
    publishTimeMs,
    supportedMedia,
  };
});

const unclassifiedCandidates = normalizedList.filter((row) =>
  row.id && row.postPrefix && !row.mimeType,
);
if (unclassifiedCandidates.length) {
  throw new Error(
    "livia_missing_drive_mime_type: List Files must return mimeType for scheduled media: " +
      unclassifiedCandidates.map((row) => row.name || row.id).join(", "),
  );
}

const readyGroups = new Map();
for (const row of normalizedList) {
  if (!row.supportedMedia) continue;
  if (!row.postPrefix) continue;
  if (!Number.isFinite(row.publishTimeMs)) continue;
  if (row.publishTimeMs > nowMs) continue;

  const existing = readyGroups.get(row.postPrefix);
  if (!existing || row.publishTimeMs < existing.publishTimeMs) {
    readyGroups.set(row.postPrefix, { postPrefix: row.postPrefix, publishTimeMs: row.publishTimeMs });
  }
}

let selectedPrefixes = new Set();
if (readyGroups.size) {
  const newestPublishTimeMs = Math.max(...Array.from(readyGroups.values()).map((row) => row.publishTimeMs));
  selectedPrefixes = new Set(
    Array.from(readyGroups.values())
      .filter((row) => row.publishTimeMs === newestPublishTimeMs)
      .map((row) => row.postPrefix),
  );
}

const selectedList = normalizedList
  .filter((row) => selectedPrefixes.has(row.postPrefix))
  .sort((left, right) => {
    if (left.publishTimeMs !== right.publishTimeMs) return left.publishTimeMs - right.publishTimeMs;
    return str(left.name).localeCompare(str(right.name));
  });

const output = selectedList.map((current) => {
  const sourceItem = items[current._inputIndex];
  const postPrefix = current.postPrefix;
  const targetDate = current.targetDate;
  const groupKey = postPrefix ? `dt:${postPrefix}`: "";

  const groupRows = selectedList
    .filter((row) => row.postPrefix === postPrefix)
    .sort((left, right) => str(left.name || "", "").localeCompare(str(right.name || "", "")));

  const groupOrder = Math.max(0, groupRows.findIndex((row) => str(row.id || "", "") === current.id));
  const quantity = groupRows.length || 1;
  const mimeTypes = groupRows.map((row) => str(row.mimeType, "").toLowerCase());
  const hasVideo = mimeTypes.some((value) => value.startsWith("video/"));
  const hasImage = mimeTypes.some((value) => value.startsWith("image/"));
  const groupIsVideo = hasVideo && !hasImage;
  const groupHasMixedMedia = hasVideo && hasImage;
  const groupIsHomogeneous = !groupHasMixedMedia;
  const isMulti = quantity > 1;
  const groupBaseMediaType = groupIsVideo ? "VIDEO" : "IMAGE";
  const media_type = isMulti ? "CAROUSEL" : groupBaseMediaType;
  const media_type_instagram = groupIsVideo ? "REELS" : (isMulti ? "CAROUSEL" : "IMAGE");
  const edge = groupIsVideo ? "videos" : "photos";

  return {
    json: {
      targetDate,
      postPrefix,
      groupKey,
      groupOrder,
      id: current.id,
      name: current.name,
      mimeType: current.mimeType,
      publishTime: current.publishTime,
      quantity,
      isMulti,
      groupBaseMediaType,
      groupIsVideo,
      groupIsHomogeneous,
      groupHasMixedMedia,
      multi_share_optimized: isMulti ? "TRUE" : "FALSE",
      is_carousel_item: isMulti ? "TRUE" : "FALSE",
      media_type,
      media_type_1st_requisition: media_type,
      media_type_2nd_requisition: media_type,
      media_type_instagram,
      edge,
      supportedMedia: current.supportedMedia,
    },
    pairedItem: current._pairedItem || sourceItem?.pairedItem || { item: current._inputIndex },
  };
});

try {
  const sd = $getWorkflowStaticData("global");
  const execId = str($execution?.id, "noexec");
  sd.__liviaCompose1 ||= {};

  for (const key of Object.keys(sd.__liviaCompose1)) {
    if (key !== execId) delete sd.__liviaCompose1[key];
  }

  const store = { __items: output };
  for (const item of output) {
    const row = item.json || {};
    const base = fileBase(row.name);
    const keys = [
      row.id,
      row.name,
      row.groupKey,
      base,
      row.groupKey && row.id ? String(row.groupKey) + "|" + String(row.id) : "",
      row.groupKey && row.name ? String(row.groupKey) + "|" + String(row.name) : "",
      row.groupKey && base ? String(row.groupKey) + "|" + String(base) : "",
    ];

    for (const key of keys) {
      pushStoreKey(store, key, row);
    }
  }

  sd.__liviaCompose1[execId] = store;
} catch {}

return output;

parameters.jsonOutput:
={{ (() => {
  const upload = ($json && typeof $json === "object") ? $json : {};
  const media = (() => {
    try {
      return $("Prepare Media Upload Batch").item.json || {};
    } catch {
      return {};
    }
  })();

  function str(value, fallback = "") {
    return value === undefined || value === null ? fallback : String(value);
  }

  function asObj(value) {
    return value && typeof value === "object" && !Array.isArray(value) ? value : {};
  }

  function asArray(value) {
    return Array.isArray(value) ? value : [];
  }

  function num(value, fallback = 0) {
    const parsed = Number(value);
    return Number.isFinite(parsed) ? parsed : fallback;
  }

  function uniq(arr) {
