        byUnit[unitKey].fbId = str((isMetaAdsPublish && metaAdsPublish.page_id) || token.fbId || token.external_account_id, "");
        byUnit[unitKey].fbToken = "__TOKEN_GATEWAY__";
        byUnit[unitKey].fbCredentialPurpose = isMetaAdsPublish ? "meta_ads_publish_fallback" : "organic_publish";
      } else if (token.provider === "instagram") {
        byUnit[unitKey].igId = str(token.igId || token.external_account_id, "");
        byUnit[unitKey].igToken = "__TOKEN_GATEWAY__";
      } else if (token.provider === "threads") {
        byUnit[unitKey].thId = str(token.thId || token.external_account_id, "");
        byUnit[unitKey].thToken = "__TOKEN_GATEWAY__";
      }
    }

    return {
      raw: asObj(root),
      facebook: {
        network: "facebook.com",
        version: "v25.0",
        id_bss: str(byUnit.bss.fbId, ""),
        id_nh: str(byUnit.nh.fbId, ""),
        token_bss: str(byUnit.bss.fbToken, ""),
        token_nh: str(byUnit.nh.fbToken, ""),
        endpoint_1st: "",
